<?php
 if ( ! defined( 'ABSPATH' ) ) { exit; } function hvm_post_id() { $id = get_the_ID(); if ( ! $id && function_exists( 'get_queried_object_id' ) ) { $id = get_queried_object_id(); } return $id; } function hvm_get( $key, $post_id = 0 ) { $post_id = $post_id ? $post_id : hvm_post_id(); return get_post_meta( $post_id, hvm_meta_key( $key ), true ); } function hvm_rows( $key, $post_id = 0 ) { $val = hvm_get( $key, $post_id ); return is_array( $val ) ? $val : array(); } function hvm_gallery( $key = 'gallery', $post_id = 0 ) { $val = hvm_get( $key, $post_id ); if ( is_array( $val ) ) { return array_filter( array_map( 'absint', $val ) ); } return array_filter( array_map( 'absint', explode( ',', (string) $val ) ) ); } function hvm_img_url( $id, $size = 'large' ) { $id = absint( $id ); $url = $id ? wp_get_attachment_image_url( $id, $size ) : ''; if ( ! $url && class_exists( '\Elementor\Utils' ) ) { $url = \Elementor\Utils::get_placeholder_image_src(); } return $url; } function hvm_event_datetime( $post_id = 0 ) { $raw = hvm_get( 'event_date', $post_id ); if ( ! $raw ) { return array( 'ts' => 0, 'date' => '', 'time' => '' ); } $ts = strtotime( $raw ); return array( 'ts' => $ts, 'date' => $ts ? date_i18n( 'M j, Y', $ts ) : '', 'time' => $ts ? date_i18n( 'H:i', $ts ) : '', ); } 